/**
 * Generated by scripts/generate-service-icons.mjs from integrations/<id>/icon.svg. Do not edit.
 *
 * Which services Authlane ships a mark for. Not every owner permits theirs to be redistributed, so
 * a service missing from this list renders from its brand colour and initials instead.
 */

export const SERVICE_IDS_WITH_ICON: readonly string[] = Object.freeze([
  'airtable',
  'discord',
  'github',
  'gmail',
  'google-calendar',
  'google-drive',
  'hubspot',
  'jira',
  'linear',
  'notion',
  'stripe',
]);

const withIcon = new Set(SERVICE_IDS_WITH_ICON);

export function hasServiceIcon(serviceId: string): boolean {
  return withIcon.has(serviceId);
}
